// Sample artwork bundled in public/images (generated by
// scripts/generate-sample-images.mjs). Seeded artists/albums get their own
// image; anything created later through the app falls back to a generic one.

const slug = (s = '') => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');

const SEEDED_ARTISTS = new Set([
    'nova-ray', 'eclipse', 'vortex', 'luna-skye', 'atlas', 'drift-theory', 'neon-fable', 'rust-bloom',
]);
const SEEDED_ALBUM_COUNT = 18;
const DEFAULT_ALBUM_COUNT = 6;

export function artistImage(name) {
    const s = slug(name);
    return `/images/artists/${SEEDED_ARTISTS.has(s) ? s : 'default'}.svg`;
}

export function artistBanner(name) {
    const s = slug(name);
    return `/images/artists/${SEEDED_ARTISTS.has(s) ? s : 'default'}-banner.svg`;
}

export function albumCover(albumId) {
    const id = Number(albumId);
    if (id >= 1 && id <= SEEDED_ALBUM_COUNT) return `/images/albums/album-${id}.svg`;
    const n = Number.isFinite(id) && id > 0 ? (id % DEFAULT_ALBUM_COUNT) + 1 : 1;
    return `/images/albums/default-${n}.svg`;
}

// Songs use their album's cover.
export const songCover = (song) => albumCover(song?.album_id);
